from pathlib import Path
s=Path('astra-remaining-improvements/stage/993e7c3b44d7')
def put(name,text):
 p=s/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding='utf-8')
put('src/lib/puzzles/validation.js','''export class InputError extends Error { constructor(message,status=400){super(message);this.status=status;} }
export function object(value,keys){if(!value||typeof value!=="object"||Array.isArray(value))throw new InputError("Expected an object.");if(Object.keys(value).some(key=>!keys.includes(key)))throw new InputError("Unknown field.");return value;}
export function text(value,max,label){if(typeof value!=="string"||!value.trim()||value.trim().length>max)throw new InputError(`${label} must contain 1–${max} characters.`);return value.trim();}
export function dateString(value){if(typeof value!=="string"||!/^\\d{4}-\\d{2}-\\d{2}$/.test(value)||value<'2000-01-01'||value>'2100-12-31')throw new InputError("Date must be YYYY-MM-DD between 2000 and 2100.");const date=new Date(value+'T00:00:00.000Z');if(!Number.isFinite(date.getTime())||date.toISOString().slice(0,10)!==value)throw new InputError("Date is not a real calendar day.");return value;}
export function localeValue(value){if(typeof value!=="string"||!['en-US','en-GB'].includes(value))throw new InputError("Locale must be en-US or en-GB.");return value;}
export function versionValue(value){if(!Number.isSafeInteger(value)||value<1||value>=2147483647)throw new InputError("Version must be a positive bounded integer.");return value;}
export function puzzleDraft(value){object(value,['title','date','locale','rootLabel','categories']);const title=text(value.title,120,'Title'),date=dateString(value.date),locale=localeValue(value.locale),rootLabel=text(value.rootLabel,80,'Root label');if(!Array.isArray(value.categories)||value.categories.length!==4)throw new InputError("A mini puzzle requires exactly four categories.");const categories=value.categories.map(item=>{object(item,['label','hint','members']);const label=text(item.label,80,'Category label');if(typeof item.hint!=='string'||item.hint.length>16)throw new InputError("Hint must be text of at most 16 characters.");if(!Array.isArray(item.members)||item.members.length!==4)throw new InputError("Each category requires four members.");return {label,hint:item.hint.trim(),members:item.members.map(member=>text(member,60,'Member'))};});const unique=values=>new Set(values.map(v=>v.toLocaleLowerCase('en-US'))).size===values.length;if(!unique(categories.map(c=>c.label))||!unique(categories.flatMap(c=>c.members)))throw new InputError("Category labels and all sixteen members must be unique, ignoring case.");return {title,date,locale,rootLabel,categories};}
export function dailyFilters(params){for(const key of params.keys()){if(!['locale','size','date'].includes(key)||params.getAll(key).length!==1)throw new InputError("Unknown or repeated filter.");}const size=(params.get('size')??'mini').toLowerCase();if(!['mini','big'].includes(size))throw new InputError("Size must be mini or big.");return {locale:localeValue(params.get('locale')??'en-US'),size,date:dateString(params.get('date')??new Date().toISOString().slice(0,10))};}
export function listFilters(params){for(const key of params.keys()){if(!['q','page','status'].includes(key)||params.getAll(key).length!==1)throw new InputError("Unknown or repeated filter.");}const raw=params.get('page')??'1';if(!/^[1-9]\\d{0,4}$/.test(raw))throw new InputError("Page must be between 1 and 99999.");const q=params.get('q')??'';if(q.length>120)throw new InputError("Search is limited to 120 characters.");const status=params.get('status')??'all';if(!['all','draft','published','archived'].includes(status))throw new InputError("Unknown puzzle status.");return {q:q.trim(),page:Number(raw),status};}
''')
put('src/lib/puzzles/authoring.js','''import {randomUUID} from 'node:crypto';
import {InputError,puzzleDraft,versionValue} from './validation.js';
export function draftGroups(draft,puzzleId){const rootId=randomUUID();return [{id:rootId,puzzleId,level:1,groupIndex:0,themeLabel:draft.rootLabel,emojiHint:'',members:draft.categories.map(c=>c.label),parentGroupId:null},...draft.categories.map((c,index)=>({id:randomUUID(),puzzleId,level:0,groupIndex:index,themeLabel:c.label,emojiHint:c.hint,members:c.members,parentGroupId:rootId}))];}
export function asDraft(puzzle){const root=puzzle.groups.find(g=>g.level===1&&!g.parentGroupId);const leaves=puzzle.groups.filter(g=>g.level===0).sort((a,b)=>a.groupIndex-b.groupIndex);return {title:puzzle.title??'',date:puzzle.date?.toISOString().slice(0,10)??'',locale:puzzle.locale,rootLabel:root?.themeLabel??'',categories:leaves.map(g=>({label:g.themeLabel,hint:g.emojiHint??'',members:g.members}))};}
export function detail(puzzle){return {...puzzle,draft:asDraft(puzzle),state:puzzle.isPublished?'published':puzzle.publishedAt?'archived':'draft'};}
const include={groups:{orderBy:[{level:'desc'},{groupIndex:'asc'}]}};
async function current(tx,id,version){const row=await tx.puzzle.findUnique({where:{id},include});if(!row)throw new InputError('Puzzle not found.',404);if(row.version!==version)throw new InputError('Puzzle changed. Keep your draft and load current data before retrying.',409);return row;}
async function audit(tx,id,action,version){await tx.puzzleAudit.create({data:{puzzleId:id,action,version}});}
function dateValue(date){return new Date(date+'T00:00:00.000Z');}
export async function createPuzzle(db,input){const draft=puzzleDraft(input);return db.$transaction(async tx=>{const id=randomUUID();await tx.puzzle.create({data:{id,title:draft.title,date:dateValue(draft.date),locale:draft.locale,size:'MINI',type:'DAILY'}});await tx.puzzleGroup.createMany({data:draftGroups(draft,id)});await audit(tx,id,'CREATE',1);return detail(await tx.puzzle.findUniqueOrThrow({where:{id},include}));});}
export async function updatePuzzle(db,id,version,input){versionValue(version);const draft=puzzleDraft(input);return db.$transaction(async tx=>{const row=await current(tx,id,version);if(row.publishedAt||row.isPublished)throw new InputError('Published puzzle content is immutable. Create a new draft.',409);const changed=await tx.puzzle.updateMany({where:{id,version,publishedAt:null,isPublished:false},data:{title:draft.title,date:dateValue(draft.date),locale:draft.locale,version:{increment:1}}});if(changed.count!==1)throw new InputError('Puzzle changed while saving.',409);await tx.puzzleGroup.deleteMany({where:{puzzleId:id}});await tx.puzzleGroup.createMany({data:draftGroups(draft,id)});await audit(tx,id,'UPDATE',version+1);return detail(await tx.puzzle.findUniqueOrThrow({where:{id},include}));});}
export async function publishPuzzle(db,id,version,published){versionValue(version);if(typeof published!=='boolean')throw new InputError('Published must be boolean.');return db.$transaction(async tx=>{const row=await current(tx,id,version);if(row.size!=='MINI'||row.type!=='DAILY')throw new InputError('Authoring currently supports daily mini puzzles only.',409);puzzleDraft(asDraft(row));if(row.isPublished===published)throw new InputError('Puzzle already has this publication state.',409);const changed=await tx.puzzle.updateMany({where:{id,version},data:{isPublished:published,publishedAt:row.publishedAt??(published?new Date():null),version:{increment:1}}});if(changed.count!==1)throw new InputError('Puzzle changed while publishing.',409);await audit(tx,id,published?'PUBLISH':'ARCHIVE',version+1);return detail(await tx.puzzle.findUniqueOrThrow({where:{id},include}));});}
export async function deletePuzzle(db,id,version){versionValue(version);return db.$transaction(async tx=>{const row=await current(tx,id,version);if(row.publishedAt||row.isPublished||await tx.gameResult.count({where:{puzzleId:id}}))throw new InputError('Only never-published drafts without results can be deleted.',409);const removed=await tx.puzzle.deleteMany({where:{id,version,publishedAt:null,isPublished:false}});if(removed.count!==1)throw new InputError('Puzzle changed while deleting.',409);await audit(tx,id,'DELETE',version+1);return {id};});}
export async function getPuzzle(db,id){const row=await db.puzzle.findUnique({where:{id},include});if(!row)throw new InputError('Puzzle not found.',404);return detail(row);}
export async function listPuzzles(db,{q,page,status}){const where={AND:[{title:{contains:q,mode:'insensitive'}},...(status==='draft'?[{isPublished:false,publishedAt:null}]:status==='published'?[{isPublished:true}]:status==='archived'?[{isPublished:false,publishedAt:{not:null}}]:[])]};const [total,rows]=await db.$transaction([db.puzzle.count({where}),db.puzzle.findMany({where,orderBy:[{date:'desc'},{id:'asc'}],skip:(page-1)*20,take:20,select:{id:true,title:true,date:true,locale:true,size:true,type:true,version:true,isPublished:true,publishedAt:true}})],{isolationLevel:'RepeatableRead'});return {total,page,pageSize:20,items:rows.map(row=>({...row,state:row.isPublished?'published':row.publishedAt?'archived':'draft'}))};}
''')
p=s/'prisma/schema.prisma';t=p.read_text(encoding='utf-8').replace('  isPublished Boolean       @default(false)','  isPublished Boolean       @default(false)\n  publishedAt DateTime?\n  version     Int           @default(1)');t+='''\n// Retained after draft deletion; no cascading relation to the mutable puzzle.
model PuzzleAudit {
  id String @id @default(cuid())
  puzzleId String
  action String
  version Int
  createdAt DateTime @default(now())
  @@index([puzzleId, createdAt])
}
''';p.write_text(t,encoding='utf-8')
put('src/app/layout.js','''import './globals.css';
export const metadata={title:'Globs Puzzle Studio',description:'Daily grouping puzzles and a local puzzle-authoring workshop.'};
export default function RootLayout({children}){return <html lang="en"><body className="antialiased">{children}</body></html>;}
''')
p=s/'src/app/globals.css';t=p.read_text(encoding='utf-8');t+='\n:root { --font-space-grotesk: Arial, Helvetica, sans-serif; --font-ibm-plex-mono: Consolas, monospace; }\n';p.write_text(t,encoding='utf-8')
p=s/'.gitignore';p.write_text(p.read_text(encoding='utf-8')+'\n!.env.example\n/test-results/\n/playwright-report/\n/.verification/\n',encoding='utf-8')
